+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * Filter understood by {@link CustomerRepository}.
+ *
+ * @param name     whitespace separated terms, each of which must occur in the first or last name
+ * @param statuses accepted statuses; empty means every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
+    }
+
+    boolean matches(Customer customer, String[] terms) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        if (terms.length == 0) {
+            return true;
+        }
+        String first = fold(customer.firstName());
+        String last = fold(customer.lastName());
+        for (String term : terms) {
+            if (!first.contains(term) && !last.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    String[] terms() {
+        String folded = fold(name).trim();
+        return folded.isEmpty() ? new String[0] : folded.split("\\s+");
+    }
+
+    static String fold(String text) {
+        return Normalizer.normalize(text, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
